13	  struct gk_collisionless *gkcls, const struct gkyl_array *fin)
14	{
15	  // Compute the surface expansion of the phase space flux
16	  // Note: Each cell stores the *lower* surface expansions of the 
17	  // phase space flux, so local_ext range needed to index the output
18	  // values of flux_surf even though we only loop over local ranges
19	  // to avoid evaluating quantities such as geometry in ghost cells
20	  // where they are not defined.
21	  gkyl_gk_collisionless_flux_surf(gkcls->surf_flux_op, 
22	    &app->local, &species->local, &app->local_ext, &species->local_ext, 
23	    species->gyro_phi, fin, gkcls->yfield, gkcls->flux_surf, species->cflrate);
