26	static void
27	gk_species_collisionless_rhs_disabled(gkyl_gyrokinetic_app *app, struct gk_species *species,
28	  struct gk_collisionless *gkcls, const struct gkyl_array *fin, struct gkyl_array *rhs)
29	{
30	}
