32	static void
33	gk_species_collisionless_rhs_enabled(gkyl_gyrokinetic_app *app, struct gk_species *species,
34	  struct gk_collisionless *gkcls, const struct gkyl_array *fin, struct gkyl_array *rhs)
35	{
36	  struct timespec wst = gkyl_wall_clock();
37	
38	  gkcls->flux_func(app, species, gkcls, fin);
39	
40	  gkyl_dg_updater_gyrokinetic_advance(gkcls->slvr, &species->local, 
41	    fin, species->cflrate, rhs);
42	
43	  gkcls->fdot_scaling(app, species, gkcls, rhs, species->cflrate, &species->local);
44	
45	  app->stat.species_collisionless_tm += gkyl_time_diff_now_sec(wst);
46	}
